with base as (select *, datediff(ends_on, starts_on) as days_starts_on_to_ends_on, concat(channel, ' - ', promo_code) as channel_promo_code from promotions where ends_on >= date '2023-07-30') select date_trunc('year', ends_on) as year_start, count(distinct id) as distinct_ids, count(distinct promo_code) as distinct_promo_codes from base group by 1 order by distinct_promo_codes nulls last;
